INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES
(24498, 'plPL', 'Droga do cytadeli', 'Zagonili naszych pojmanych żołnierzy do pracy w kamieniołomie! Zabij ich strażników i uwolnij ich, $gbohaterze:bohaterko;, i to szybko. Będziemy potrzebować ich pomocy, gdy staniemy przed Władcą Plagi Tyrannusem.', 'Uwolnij 15 niewolników Przymierza i zabij Mistrza Kuźni Garfrosta.', '', 'Porozmawiaj z Martinem Victusem przy wzniesieniu Garfrosta.', 'Uwolnieni niewolnicy Przymierza', '', '', '', 0),
(24507, 'plPL', 'Droga do cytadeli', 'Zagonili naszych pojmanych żołnierzy do pracy w kamieniołomie. Zabij ich strażników i uwolnij ich, $N, i to szybko. Będziemy potrzebować ich pomocy, gdy staniemy przed Władcą Plagi Tyrannusem.', 'Uwolnij 15 niewolników Hordy i zabij Mistrza Kuźni Garfrosta.', '', 'Porozmawiaj z Gorkunem Żelazną Czaszką przy wzniesieniu Garfrosta.', 'Uwolnieni niewolnicy Hordy', '', '', '', 0),
(24682, 'plPL', 'Czeluść Saronu', 'Szybko, przez portal! Odnajdę cię po drugiej stronie.', 'Spotkaj się z Lady Sylwaną Bieżywiatr tuż za wejściem do Czeluści Saronu.', '', '', '', '', '', '', 0),
(24683, 'plPL', 'Czeluść Saronu', 'Szybko, przez portal! Spotkamy się po drugiej stronie.', 'Spotkaj się z Lady Jainą Proudmoore tuż za wejściem do Czeluści Saronu.', '', '', '', '', '', '', 0),
(24710, 'plPL', 'Wybawienie z czeluści', 'Musimy przedostać się główną ścieżką i przez jaskinię na wzniesienie Tyrannusa. Tam będzie musiał stawić nam czoła, inaczej wedrzemy się do samej cytadeli.$B$BIdź już, $N. Ja i moi ludzie staniemy u twego boku, gdy dojdzie do starcia z Tyrannusem.', 'Zabij Władcę Plagi Tyrannusa.', '', 'Porozmawiaj z Lady Jainą Proudmoore na tyłach Czeluści Saronu.', '', '', '', '', 0),
(24712, 'plPL', 'Wybawienie z czeluści', 'Musimy przedostać się główną ścieżką i przez jaskinię na wzniesienie Tyrannusa. Tam będzie musiał stawić nam czoła, inaczej wedrzemy się do samej cytadeli.$B$BIdź już, $N. Ja i moi ludzie staniemy u twego boku, gdy dojdzie do starcia z Tyrannusem.', 'Zabij Władcę Plagi Tyrannusa.', '', 'Porozmawiaj z Lady Sylwaną Bieżywiatr na tyłach Czeluści Saronu.', '', '', '', '', 0);
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES
(24498, 'plPL', 'Dobrze się dziś $gspisałeś:spisałaś;. Skoro wielu niewolników jest wolnych, a my mamy dostęp do kuźni, niedługo zbiorę silny oddział, który pomoże nam wyrwać się spod władzy Władcy Plagi Tyrannusa i z tej plugawej czeluści.', 0),
(24507, 'plPL', 'Dobrze się dziś $gspisałeś:spisałaś;. Skoro wielu niewolników jest wolnych, a my mamy dostęp do kuźni, niedługo zbiorę silny oddział, który pomoże nam wyrwać się spod władzy Władcy Plagi Tyrannusa i z tej plugawej czeluści.', 0),
(24682, 'plPL', 'Niezdolni głupcy. Zaczynam się zastanawiać, czy którykolwiek z tych prostaków z turnieju na cokolwiek się przyda. Może udowodnisz, że się mylę.', 0),
(24683, 'plPL', 'Nie doceniłam tego Władcy Plagi, a zapłacili za to moi ludzie. Ilekroć myślę, że moje poczucie winy za zdradę Arthasa nie może być już głębsze, on znów udowadnia, że się mylę.$B$BMusimy iść dalej. Nie możemy pozwolić, by ich ofiara poszła na marne.', 0),
(24710, 'plPL', 'Co za bezsensowne marnotrawstwo! Arthas posuwa się za daleko! Mogę tylko mieć nadzieję, że to, co znajdziemy w Salach Odbić, jakoś to wynagrodzi.$B$BJeśli można wierzyć temu nikczemnemu gnomowi, powinno tam być Ostrze Mrozu, a wraz z nim odpowiedź, jak stawić czoła Arthasowi.', 0),
(24712, 'plPL', 'Przed nami Sale Odbić. Jeśli można wierzyć temu nikczemnemu gnomowi, powinno tam być Ostrze Mrozu, a wraz z nim odpowiedź, jak stawić czoła Arthasowi.', 0);
