INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `MaleText`, `FemaleText`, `VerifiedBuild`) VALUES
(36444, 'plPL', 'Garfrost zmęczony marnymi śmiertelnikami. Teraz wasze kości zamarzną!', '', 0),
(36445, 'plPL', 'Topór za słaby. Garfrost zrobić lepszy i ZMIAŻDŻYĆ WAS.', '', 0),
(36529, 'plPL', '%s cię goni. Uciekaj!', '', 0),
(36531, 'plPL', '%s zaczyna wypuszczać toksyczną chmurę trucizny!', '', 0),
(36628, 'plPL', '%s ryczy i wzbiera mroczną mocą!', '', 0),
(36648, 'plPL', 'Szronokle, zniszcz tego głupca!', '', 0),
(36649, 'plPL', 'Żmij mrozu Szronokieł wpatruje się w $n i szykuje lodowy atak!', '', 0),
(36708, 'plPL', 'Wasz pościg pójdzie na marne, intruzi, bo Król Lisz oddał pod moje rozkazy armię nieumarłych! Patrzcie!', 'Wasz pościg pójdzie na marne, intruzi, bo Król Lisz oddał pod moje rozkazy armię nieumarłych! Patrzcie!', 0),
(36709, 'plPL', 'Uparte szczeniaki! Nie dotrzecie do wejścia do leża mojego pana! Żołnierze, zniszczcie ich!', 'Uparte szczeniaki! Nie dotrzecie do wejścia do leża mojego pana! Żołnierze, zniszczcie ich!', 0),
(36718, 'plPL', 'Tędy! Zaraz uderzamy na pozycję Władcy Plagi!', 'Tędy! Zaraz uderzamy na pozycję Władcy Plagi!', 0),
(36845, 'plPL', '', 'Czemu Królowa Banshee miałaby oszczędzić twoje nędzne życie?', 0),
(36846, 'plPL', '', 'Ostrze Mrozu? Król Lisz nigdy nie rozstaje się ze swoim ostrzem. Jeśli mnie okłamujesz...', 0),
(36847, 'plPL', '', 'Odpowiedni koniec dla zdrajcy. Chodźcie, musimy uwolnić niewolników i sami zobaczyć, co kryje komnata Króla Lisza.', 0),
(36852, 'plPL', 'Bezwartościowy komarze! Czeka cię tylko śmierć!', '', 0),
(36853, 'plPL', 'Nie myślcie, że tak łatwo wpuszczę was do sanktuarium mojego pana. Gońcie mnie, jeśli się odważycie.', '', 0),
(36854, 'plPL', '', 'Nie jestem na tyle naiwna, by wierzyć w twoje błaganie o łaskę, ale wysłucham cię.', 0),
(36855, 'plPL', '', 'Cóż za okrutny koniec. Chodźcie, bohaterowie. Musimy sprawdzić, czy opowieść gnoma jest prawdziwa. Jeśli zdołamy oddzielić Arthasa od Ostrza Mrozu, może będziemy mieli szansę go powstrzymać.', 0),
(36856, 'plPL', '', 'Ostrze Mrozu pozostawione bez straży? Niemożliwe!', 0),
(37079, 'plPL', 'Prawie straciłem nadzieję.', 'Prawie straciłem nadzieję.', 0),
(37087, 'plPL', '', 'Bohaterowie Przymierza, do ataku!', 0),
(37088, 'plPL', '', 'NIE! TY POTWORZE!', 0),
(37089, 'plPL', '', 'Robię, co muszę. Wybaczcie mi, szlachetni żołnierze.', 0),
(37090, 'plPL', '', 'Przez ten kamieniołom będziecie musieli przedrzeć się sami.', 0),
(37091, 'plPL', '', 'Uwalniajcie każdego niewolnika Przymierza, na którego traficie. Z pewnością będziemy potrzebować ich pomocy w walce z Tyrannusem. Zbiorę posiłki i dołączę do was po drugiej stronie kamieniołomu.', 0),
(37093, 'plPL', 'Intruzi wtargnęli do domeny mistrza. Podnieść alarm!', '', 0),
(37094, 'plPL', 'Hmpf, mięso armatnie. Nie nadają się nawet do pracy w kamieniołomie. Rozkoszujcie się tymi ostatnimi chwilami, bo wkrótce będziecie tylko bezmyślnymi nieumarłymi.', '', 0),
(37095, 'plPL', 'Waszym ostatnim wspomnieniem na jawie będzie straszliwy ból.', '', 0),
(37096, 'plPL', 'Sługi, zniszczcie tych intruzów!', '', 0),
(37178, 'plPL', 'Mistrz kuźni nie żyje! Uzbrójcie się, chłopcy, mamy Władcę Plagi do zabicia.', '', 0),
(37218, 'plPL', 'Malutkie stworki pod nogami, przynieście Garfrostowi coś dobrego do jedzenia!', '', 0),
(37219, 'plPL', 'Zostawić na przekąskę. Na później.', '', 0),
(37220, 'plPL', 'Tamten chyba już nie taki dobry do jedzenia. Głupi Garfrost! NIEDOBRY! NIEDOBRY!', '', 0),
(37221, 'plPL', 'Garfrost mieć nadzieję, że wielkie gacie czyste. Oszczędzić szefowi wielki wstyd. Na później.', '', 0),
(37232, 'plPL', 'Bohaterowie! Będziemy powstrzymywać nieumarłych, jak długo zdołamy, choćby do ostatniego tchu. Rozprawcie się z Władcą Plagi!', '', 0),
(37233, 'plPL', 'Niestety, dzielni, dzielni poszukiwacze przygód, wasze wścibstwo dobiegło końca. Słyszycie ten chrzęst kości i stali w tunelu za wami? To odgłos waszej nadciągającej zguby.', '', 0),
(37234, 'plPL', 'Ha, cóż za zabawny gest motłochu. Gdy z wami skończę, ostrze mojego pana nasyci się waszymi duszami. Giń.', '', 0),
(37260, 'plPL', '%s rzuca |cFF00AACCGłębokie mrożenie|r na $n.', '', 0),
(37262, 'plPL', 'Myślałem, że zginę w tej czeluści. Dziękuję!', 'Myślałem, że zginę w tej czeluści. Dziękuję!', 0),
(37263, 'plPL', 'Stawiam ci całą noc picia, $gprzyjacielu:przyjaciółko;.', 'Chcę mieć z tobą dzieci.', 0),
(37264, 'plPL', 'Nie zostawiaj przy życiu ani jednego z nich.', 'Nie zostawiaj przy życiu ani jednego z nich.', 0),
(37265, 'plPL', 'Proszę, dokonaj naszej zemsty na Władcy Plagi.', 'Proszę, dokonaj naszej zemsty na Władcy Plagi.', 0),
(37266, 'plPL', 'Kiedy zabijesz Mistrza Czeluści, splunij za mnie na jego trupa, dobrze?', 'Kiedy zabijesz Mistrza Czeluści, splunij za mnie na jego trupa, dobrze?', 0),
(37268, 'plPL', 'W tym przeklętym miejscu straciłem rachubę czasu. Miło cię widzieć, $gprzyjacielu:przyjaciółko;.', 'W tym przeklętym miejscu straciłem rachubę czasu. Miło cię widzieć, $gprzyjacielu:przyjaciółko;.', 0),
(37269, 'plPL', 'Nawet nie wiesz, jak pięknie wyglądasz.', 'Nawet nie wiesz, jak pięknie wyglądasz.', 0),
(37270, 'plPL', 'Zbyt wielu z nas zginęło w tej czeluści. O wiele za wielu.', 'Zbyt wielu z nas zginęło w tej czeluści. O wiele za wielu.', 0),
(37271, 'plPL', 'Tak się cieszę, że tu jesteś. Długo bym już nie wytrzymał.', 'Tak się cieszę, że tu jesteś. Długo bym już nie wytrzymał.', 0),
(37273, 'plPL', 'Teraz czas na zemstę.', 'Teraz czas na zemstę.', 0),
(37274, 'plPL', 'Należy ci się potężny męski uścisk.', 'Mógłbym cię wycałować!', 0),
(37275, 'plPL', 'Kiedyś znajdę sposób, by ci się odwdzięczyć, $gbohaterze:bohaterko;.', 'Kiedyś znajdę sposób, by ci się odwdzięczyć, $gbohaterze:bohaterko;.', 0),
(37276, 'plPL', 'Nie wierzę własnym oczom. Dziękuję. Naprawdę, dziękuję.', 'Nie wierzę własnym oczom. Dziękuję. Naprawdę, dziękuję.', 0),
(37277, 'plPL', '%s kiwa głową w podziękowaniu.', '%s kiwa głową w podziękowaniu.', 0),
(37278, 'plPL', '%s uśmiecha się z wdzięcznością.', '%s uśmiecha się z wdzięcznością.', 0),
(37279, 'plPL', '%s niemal się przewraca, zataczając się w twoją stronę.', '%s niemal się przewraca, zataczając się w twoją stronę.', 0),
(37280, 'plPL', '%s wpatruje się w ciebie przez chwilę, wyraźnie nie mogąc uwierzyć, że jesteś $gprawdziwy:prawdziwa;.', '%s wpatruje się w ciebie przez chwilę, wyraźnie nie mogąc uwierzyć, że jesteś $gprawdziwy:prawdziwa;.', 0),
(37281, 'plPL', '%s śmieje się krótko i cynicznie ze swojego losu.', '%s śmieje się krótko i cynicznie ze swojego losu.', 0),
(37282, 'plPL', '%s wznosi pustą dłonią toast na twoją cześć.', '%s przesyła ci całusa.', 0),
(37283, 'plPL', '%s zamyka oczy, przez chwilę rozkoszując się wolnością.', '%s zamyka oczy, przez chwilę rozkoszując się wolnością.', 0),
(37284, 'plPL', '%s podchodzi, wlokąc za sobą kilof po ziemi, wyraźnie wyczerpany.', '%s podchodzi, wlokąc za sobą kilof po ziemi, wyraźnie wyczerpana.', 0),
(37287, 'plPL', 'Jeśli życiem lub śmiercią zdołam ci się odpłacić, zrobię to.', 'Jeśli życiem lub śmiercią zdołam ci się odpłacić, zrobię to.', 0),
(37293, 'plPL', 'Wracam pomóc uwolnić pozostałych niewolników. Jeszcze raz dziękuję, $gbohaterze:bohaterko;.', 'Wracam pomóc uwolnić pozostałych niewolników. Jeszcze raz dziękuję, $gbohaterze:bohaterko;.', 0),
(37294, 'plPL', 'Wracam na przód kamieniołomu. Zabij kilku więcej za mnie.', 'Wracam na przód kamieniołomu. Zabij kilku więcej za mnie.', 0),
(37320, 'plPL', 'Dzielni czempioni, zawdzięczamy wam życie i wolność... Choć to drobny gest wobec tak ogromnego długu, przysięgam, że od dziś wszyscy poznają wasze czyny i płonący szlak światła, który wycięliście w cieniu tej mrocznej cytadeli.', '', 0),
(37321, 'plPL', 'Ten dzień będzie świadectwem nie tylko waszego męstwa, ale i tego, że żaden wróg, nawet sam Król Lisz, nie ostoi się, gdy Przymierze i Horda odłożą na bok dzielące je różnice i...', '', 0),
(37369, 'plPL', '', 'Doskonała robota, czempioni! Założymy w tych komnatach obóz. Moi magowie wkrótce uruchomią urządzenie transportowe Plagi. Wejdźcie do niego, gdy będziecie gotowi na następną misję. Spotkamy się po drugiej stronie.', 0),
(37387, 'plPL', '', 'Doskonała robota, czempioni! Założymy w tych komnatach obóz. Moi magowie wkrótce uruchomią urządzenie transportowe Plagi. Wejdźcie do środka, gdy będziecie gotowi na następną misję. Spotkamy się po drugiej stronie.', 0),
(37392, 'plPL', '', 'Żołnierze Hordy, do ataku!', 0),
(37393, 'plPL', '', 'Żałosne cherlaki.', 0),
(37394, 'plPL', '', 'Przez tę kloakę będziecie musieli przebić się sami.', 0),
(37395, 'plPL', '', 'Uwalniajcie każdego niewolnika Hordy, na którego traficie. Z pewnością będziemy potrzebować ich pomocy w walce z Tyrannusem. Zbiorę posiłki i dołączę do was po drugiej stronie kamieniołomu.', 0),
(37438, 'plPL', '%s ciska w ciebie ogromnym głazem saronitu!', '', 0),
(38347, 'plPL', 'Wola Mistrza pozostaje nienaruszona...', 'Wola Mistrza pozostaje nienaruszona...', 0),
(38348, 'plPL', 'Nie uciekniesz przed gniewem Mistrza...', 'Nie uciekniesz przed gniewem Mistrza...', 0),
(38350, 'plPL', 'Król Lisz jest nie do powstrzymania...', 'Król Lisz jest nie do powstrzymania...', 0),
(38351, 'plPL', 'Poddaj się... zimnym objęciom śmierci...', 'Poddaj się... zimnym objęciom śmierci...', 0),
(38352, 'plPL', 'Uwolnij się z łańcuchów życia...', 'Uwolnij się z łańcuchów życia...', 0),
(38353, 'plPL', 'Śmierć cię pochłania...', 'Śmierć cię pochłania...', 0),
(38354, 'plPL', 'On obserwuje każdy twój ruch...', 'On obserwuje każdy twój ruch...', 0),
(38355, 'plPL', 'Krzycz w męczarniach... Niech ból przemoże twoją siłę...', 'Krzycz w męczarniach... Niech ból przemoże twoją siłę...', 0),
(38714, 'plPL', 'Niemożliwe... Szronokle... ostrzeż...', '', 0),
(38715, 'plPL', 'Cóż za żałosny pokaz. Lepiej wam będzie po śmierci.', '', 0),
(38716, 'plPL', 'Może trzeba było zostać... w górach!', '', 0),
(38717, 'plPL', 'Moc... przytłaczająca!', '', 0),
(38718, 'plPL', 'Nie zawiodę Króla Lisza. Chodźcie po swój koniec!', '', 0);
